package omtteam.openmodularturrets.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.damagesource.DamageType;
import omtteam.openmodularturrets.OMT;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Damage types of turret projectiles (oldmod {@code NormalDamageSource} / {@code ArmorBypassDamageSource} names).
 * Damage types are data-driven; the JSON files are generated by datagen from {@link #DEFINITIONS}.
 */
public final class ModDamageTypes {
    /** Key → death message id ({@code death.attack.<id>}), in registration order. */
    public static final Map<ResourceKey<DamageType>, String> DEFINITIONS = new LinkedHashMap<>();

    public static final ResourceKey<DamageType> BULLET = create("bullet", "bullet");
    public static final ResourceKey<DamageType> BLAZING_CLAY = create("blazing_clay", "blazing_clay");
    public static final ResourceKey<DamageType> GRENADE = create("grenade", "grenade");
    /** oldmod {@code ArmorBypassDamageSource("grenade")}: same death message. */
    public static final ResourceKey<DamageType> GRENADE_ARMOR_BYPASS = create("grenade_armor_bypass", "grenade");
    public static final ResourceKey<DamageType> ROCKET = create("rocket", "rocket");
    public static final ResourceKey<DamageType> ARROW = create("arrow", "arrow");
    public static final ResourceKey<DamageType> POTATO = create("potato", "potato");
    public static final ResourceKey<DamageType> DISPOSABLE = create("disposable", "disposable");
    public static final ResourceKey<DamageType> PLASMA = create("plasma", "plasma");
    public static final ResourceKey<DamageType> PLASMA_ARMOR_BYPASS = create("plasma_armor_bypass", "plasma");

    // Ray and melee turrets (oldmod used the turret type name; not projectile damage)
    public static final ResourceKey<DamageType> LASER = create("laser", "laser");
    /** oldmod: the railgun only dealt armor-piercing damage. */
    public static final ResourceKey<DamageType> RAILGUN = create("railgun", "railgun");
    public static final ResourceKey<DamageType> ARC = create("arc", "arc");
    public static final ResourceKey<DamageType> ARC_ARMOR_BYPASS = create("arc_armor_bypass", "arc");
    public static final ResourceKey<DamageType> MELEE = create("melee", "melee");

    /** Types tagged {@code minecraft:bypasses_armor}. */
    public static final Set<ResourceKey<DamageType>> ARMOR_BYPASSING = Set.of(GRENADE_ARMOR_BYPASS, PLASMA_ARMOR_BYPASS,
            RAILGUN, ARC_ARMOR_BYPASS);

    /** Types tagged {@code minecraft:is_projectile} (oldmod {@code setProjectile()}). */
    public static final Set<ResourceKey<DamageType>> PROJECTILE = Set.of(BULLET, BLAZING_CLAY, GRENADE,
            GRENADE_ARMOR_BYPASS, ROCKET, ARROW, POTATO, DISPOSABLE, PLASMA, PLASMA_ARMOR_BYPASS);

    private ModDamageTypes() {
    }

    private static ResourceKey<DamageType> create(String name, String messageId) {
        ResourceKey<DamageType> key = ResourceKey.create(Registries.DAMAGE_TYPE, OMT.id(name));
        DEFINITIONS.put(key, OMT.MOD_ID + "." + messageId);
        return key;
    }

    /** All turret damage types. */
    public static Set<ResourceKey<DamageType>> all() {
        return DEFINITIONS.keySet();
    }

    /** oldmod used no exhaustion setting; 0.1 is the vanilla value for projectile damage. */
    public static DamageType create(ResourceKey<DamageType> key) {
        return new DamageType(DEFINITIONS.get(key), 0.1F);
    }
}
